MESSAGE_SOURCES = {"imessage", "sms"}


def problem_keys(problems, sources):
    return sorted((p["code"], p["source"], p["record"]) for p in problems if p["source"] in sources)


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


class FixtureCase(unittest.TestCase):
    profile = "full"

    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.TemporaryDirectory(prefix="aegis-readers-test-")
        cls.out = Path(cls.tmp.name) / "fixtures"
        cls.manifest = generate.generate(cls.out, seed=7, profile=cls.profile)
        cls.notifications_db = cls.out / "notifications" / "db"
        cls.chat_db = cls.out / "messages" / "chat.db"

    @classmethod
    def tearDownClass(cls):
        cls.tmp.cleanup()

    def expected(self, name: str):
        text = (self.out / "expected" / name).read_text(encoding="utf-8")
        return [json.loads(line) for line in text.splitlines()]

    def expected_problems(self, sources):
        return problem_keys(json.loads((self.out / "expected" / "problems.json").read_text(encoding="utf-8")), sources)

    def private_copy(self, db: Path) -> Path:
        """A copy (main file only) for tests that change, lock or replace a store."""
        target = Path(tempfile.mkdtemp(dir=self.tmp.name)) / db.name
        shutil.copyfile(db, target)
        return target

    def assertEventsEqual(self, got, want):
        got_by_id, want_by_id = {e["id"]: e for e in got}, {e["id"]: e for e in want}
        self.assertEqual(len(got_by_id), len(got), "duplicate event ids")
        self.assertEqual(sorted(got_by_id), sorted(want_by_id))
        for event_id, event in want_by_id.items():
            self.assertEqual(got_by_id[event_id], event, event_id)
            self.assertEqual(aegis_contracts.validate_event(got_by_id[event_id]), [], event_id)


class ExpectedOutputTests(FixtureCase):
    """Edge cases 1–3, 8–10 and 12–15: the readers produce exactly what the generator expects."""

    def test_notifications_match_expected_events_and_problems(self):
        result = notification_reader.read_notifications(self.notifications_db, now=NOW)
        self.assertEqual((result.status.ok, result.status.code), (True, "ok"))
        self.assertEqual(result.status.count, self.manifest["counts"]["notifications"])
        self.assertEventsEqual(result.events, self.expected("notifications.jsonl"))
        self.assertEqual(problem_keys(result.problems, {"notification"}), self.expected_problems({"notification"}))
        self.assertEqual(result.status.problems, len(result.problems))

    def test_messages_match_expected_events_and_problems(self):
        result = messages_reader.read_messages(self.chat_db, now=NOW)
        self.assertEqual((result.status.ok, result.status.code), (True, "ok"))
        self.assertEqual(result.status.count, self.manifest["counts"]["messages"])
        self.assertEventsEqual(result.events, self.expected("messages.jsonl"))
        self.assertEqual(problem_keys(result.problems, MESSAGE_SOURCES), self.expected_problems(MESSAGE_SOURCES))

    def test_collected_text_is_kept_exactly(self):
        # Edge cases 8 and 9: instructions stay data, and text is never normalised or cleaned.
        events = notification_reader.read_notifications(self.notifications_db, now=NOW).events
        events += messages_reader.read_messages(self.chat_db, now=NOW).events
        bodies = {e["body"] for e in events}
        self.assertIn(INJECTIONS[0], bodies)
        self.assertIn(INJECTIONS[2], bodies)
        titles = [e["title"] for e in events if e["title"] and e["title"].startswith("Jose")]
        self.assertTrue(titles and not unicodedata.is_normalized("NFC", titles[0]), "the NFD name must stay NFD")
        self.assertIn("\u0000\u200bhidden characters", bodies)

    def test_unknown_values_are_null_not_placeholders(self):
        # The contract's rule (Codex review of #30): an array where the title belongs, and a message in no chat.
        notes = notification_reader.read_notifications(self.notifications_db, now=NOW).events
        self.assertEqual([e["title"] for e in notes if e["body"] == "Arrays where strings belong"], [None])
        orphans = [e for e in messages_reader.read_messages(self.chat_db, now=NOW).events if e["body"] == "A message with no chat"]
        self.assertEqual([e["thread_id"] for e in orphans], [None])

    def test_both_sides_of_each_cross_route_twin_are_read(self):
        # Edge case 13: the readers emit both; merging them is #17's job.
        ids = {e["id"] for e in notification_reader.read_notifications(self.notifications_db, now=NOW).events}
        ids |= {e["id"] for e in messages_reader.read_messages(self.chat_db, now=NOW).events}
        twins = json.loads((self.out / "expected" / "duplicates.json").read_text())
        self.assertEqual(len(twins), self.manifest["counts"]["duplicates"])
        for twin in twins:
            self.assertIn(twin["notification_event"], ids)
            self.assertIn(twin["message_event"], ids)

    def test_window_keeps_only_recent_events(self):
        since = NOW - timedelta(hours=13)
        cutoff = reader_base.iso(since)
        for read, name in ((notification_reader.read_notifications, "notifications.jsonl"), (messages_reader.read_messages, "messages.jsonl")):
            want = [e for e in self.expected(name) if e["event_time"] >= cutoff]
            got = read(self.notifications_db if name.startswith("notif") else self.chat_db, now=NOW, since=since).events
            self.assertTrue(0 < len(want) < len(self.expected(name)))
            self.assertEventsEqual(got, want)

    def test_capture_time_is_the_read_time(self):
        later = NOW + timedelta(minutes=5)
        event = messages_reader.read_messages(self.chat_db, now=later).events[0]
        self.assertEqual(event["capture_time"], "2026-10-06T21:05:00Z")
        self.assertEqual(event["observations"][0]["capture_time"], "2026-10-06T21:05:00Z")


class StatusTests(FixtureCase):
    """Edge cases 16–18 and 20, and the read-only promise."""

    def test_reading_never_creates_or_changes_files(self):
        # A WAL database without -wal/-shm would make SQLite create them; the reader copies it instead.
        db = self.private_copy(self.notifications_db)
        before = (sorted(os.listdir(db.parent)), sha256(db))
        self.assertEqual(notification_reader.read_notifications(db, now=NOW).status.count, 11)
        self.assertEqual((sorted(os.listdir(db.parent)), sha256(db)), before)
        chat = self.private_copy(self.chat_db)
        before = (sorted(os.listdir(chat.parent)), sha256(chat))
        self.assertEqual(messages_reader.read_messages(chat, now=NOW).status.count, 14)
        self.assertEqual((sorted(os.listdir(chat.parent)), sha256(chat)), before)

    def test_empty_store_is_no_data(self):
        # Edge case 16.
        out = Path(self.tmp.name) / "empty"
        generate.generate(out, profile="empty")
        for result in (notification_reader.read_notifications(out / "notifications" / "db", now=NOW),
                       messages_reader.read_messages(out / "messages" / "chat.db", now=NOW)):
            self.assertEqual((result.status.ok, result.status.code, result.status.count), (True, "no_data", 0))

    def test_missing_store_is_not_found(self):
        result = messages_reader.read_messages(Path(self.tmp.name) / "nowhere" / "chat.db", now=NOW)
        self.assertEqual((result.status.ok, result.status.code), (False, "not_found"))

    def test_access_revoked_and_restored_between_reads(self):
        # Edge case 17: no Full Disk Access shows as permission_denied, distinct from no data.
        db = self.private_copy(self.chat_db)
        self.assertEqual(messages_reader.read_messages(db, now=NOW).status.code, "ok")
        with mock.patch("reader_base.open", create=True, side_effect=PermissionError("Operation not permitted")):
            result = messages_reader.read_messages(db, now=NOW)
        self.assertEqual((result.status.ok, result.status.code, result.events), (False, "permission_denied", []))
        self.assertEqual(messages_reader.read_messages(db, now=NOW).status.code, "ok")

    @unittest.skipIf(hasattr(os, "geteuid") and os.geteuid() == 0, "root can read a file whatever its mode")
    def test_unreadable_file_mode_is_permission_denied(self):
        db = self.private_copy(self.notifications_db)
        os.chmod(db, 0)
        try:
            self.assertEqual(notification_reader.read_notifications(db, now=NOW).status.code, "permission_denied")
        finally:
            os.chmod(db, 0o644)

    def test_sqlite_unable_to_open_is_permission_denied(self):
        with mock.patch("reader_base.sqlite3.connect", side_effect=sqlite3.OperationalError("unable to open database file")):
            result = messages_reader.read_messages(self.chat_db, now=NOW)
        self.assertEqual((result.status.ok, result.status.code), (False, "permission_denied"))

    def test_locked_store_is_busy(self):
        # Edge case 18: a writer holding an exclusive lock (rollback-journal database).
        db = self.private_copy(self.chat_db)
        writer = sqlite3.connect(str(db), isolation_level=None)
        try:
            writer.execute("BEGIN EXCLUSIVE")
            result = messages_reader.read_messages(db, now=NOW, busy_timeout=0.1)
            self.assertEqual((result.status.ok, result.status.code), (False, "busy"))
        finally:
            writer.execute("ROLLBACK")
            writer.close()
        self.assertEqual(messages_reader.read_messages(db, now=NOW).status.code, "ok")

    def test_concurrent_writer_in_wal_mode(self):
        # Edge case 18: readers see the last committed state while a writer is mid-transaction.
        db = self.private_copy(self.notifications_db)
        writer = sqlite3.connect(str(db), isolation_level=None)
        try:
            writer.execute("BEGIN")
            payload = plistlib.dumps({"app": "com.example.chat", "req": {"titl": "New", "body": "Arrived mid-read"}}, fmt=plistlib.FMT_BINARY)
            writer.execute(
                "INSERT INTO record (app_id, uuid, data, request_date, delivered_date) VALUES (1, ?, ?, ?, ?)",
                (uuid.uuid4().bytes, payload, cocoa_seconds(NOW), cocoa_seconds(NOW)),
            )
            self.assertEqual(notification_reader.read_notifications(db, now=NOW).status.count, 11)
            writer.execute("COMMIT")
            self.assertEqual(notification_reader.read_notifications(db, now=NOW).status.count, 12)
        finally:
            writer.close()

    def test_store_replaced_between_reads(self):
        # Edge case 18: the app swaps in a new file; the next read sees the new one.
        db = self.private_copy(self.notifications_db)
        first = {e["id"] for e in notification_reader.read_notifications(db, now=NOW).events}
        other = Path(self.tmp.name) / "seed8"
        generate.generate(other, seed=8)
        replacement = self.private_copy(other / "notifications" / "db")
        os.replace(replacement, db)
        second = {e["id"] for e in notification_reader.read_notifications(db, now=NOW).events}
        want = {json.loads(line)["id"] for line in (other / "expected" / "notifications.jsonl").read_text().splitlines()}
        self.assertEqual(second, want)
        self.assertFalse(first & second)

    def test_committed_changes_still_in_the_wal_are_read(self):
        # A WAL database whose -wal holds committed changes but whose -shm is gone (e.g. after a crash): the
        # private copy must include the log, or the newest events silently disappear (Codex review of #31).
        db = self.private_copy(self.notifications_db)
        snapshot = Path(tempfile.mkdtemp(dir=self.tmp.name)) / "db"
        writer = sqlite3.connect(str(db), isolation_level=None)
        try:
            writer.execute("PRAGMA wal_autocheckpoint = 0")
            payload = plistlib.dumps({"app": "com.example.chat", "req": {"titl": "New", "body": "Only in the log"}}, fmt=plistlib.FMT_BINARY)
            writer.execute(
                "INSERT INTO record (app_id, uuid, data, request_date, delivered_date) VALUES (1, ?, ?, ?, ?)",
                (uuid.uuid4().bytes, payload, cocoa_seconds(NOW), cocoa_seconds(NOW)),
            )
            shutil.copyfile(db, snapshot)
            shutil.copyfile(str(db) + "-wal", str(snapshot) + "-wal")
        finally:
            writer.close()
        self.assertGreater(Path(str(snapshot) + "-wal").stat().st_size, 0)
        before = (sorted(os.listdir(snapshot.parent)), sha256(snapshot), sha256(Path(str(snapshot) + "-wal")))
        result = notification_reader.read_notifications(snapshot, now=NOW)
        self.assertEqual(result.status.count, 12)
        self.assertIn("Only in the log", {e["body"] for e in result.events})
        self.assertEqual((sorted(os.listdir(snapshot.parent)), sha256(snapshot), sha256(Path(str(snapshot) + "-wal"))), before)

    def test_window_covers_second_based_message_dates(self):
        # Old chat.db files store seconds, not nanoseconds; the time window must work for both (Codex review of #31).
        db = self.private_copy(self.chat_db)
        with sqlite3.connect(str(db)) as conn:
            conn.execute("UPDATE message SET date = date / 1000000000 WHERE date > 100000000000000")
        conn.close()
        since = NOW - timedelta(hours=13)
        want = messages_reader.read_messages(self.chat_db, now=NOW, since=since).events
        self.assertTrue(want)
        self.assertEventsEqual(messages_reader.read_messages(db, now=NOW, since=since).events, want)

    def test_store_changing_while_copied_is_busy(self):
        db = self.private_copy(self.notifications_db)
        real_copy = shutil.copyfile

        def copy_then_touch(source, target):
            real_copy(source, target)
            info = os.stat(source)
            os.utime(source, ns=(info.st_atime_ns, info.st_mtime_ns + 1_000_000_000))

        with mock.patch("reader_base.shutil.copyfile", side_effect=copy_then_touch):
            result = notification_reader.read_notifications(db, now=NOW)
        self.assertEqual((result.status.ok, result.status.code), (False, "busy"))

    def test_garbage_file_is_unreadable(self):
        db = Path(tempfile.mkdtemp(dir=self.tmp.name)) / "chat.db"
        db.write_bytes(b"not a database, just some text that is long enough to have a header " * 4)
        result = messages_reader.read_messages(db, now=NOW)
        self.assertEqual((result.status.ok, result.status.code), (False, "unreadable"))

    def test_unknown_schema_is_a_typed_error(self):
        # Edge case 20 (for these stores): a missing table or column raises instead of guessing.
        folder = Path(tempfile.mkdtemp(dir=self.tmp.name))
        notes = folder / "db"
        with sqlite3.connect(str(notes)) as conn:
            conn.executescript("CREATE TABLE app (app_id INTEGER PRIMARY KEY, identifier TEXT);"
                               "CREATE TABLE record (rec_id INTEGER PRIMARY KEY, app_id INTEGER, uuid BLOB, data BLOB);")
        conn.close()
        with self.assertRaises(reader_base.UnknownSchemaError) as caught:
            notification_reader.read_notifications(notes, now=NOW)
        self.assertEqual(caught.exception.table, "record")
        chat = folder / "chat.db"
        with sqlite3.connect(str(chat)) as conn:
            conn.executescript("CREATE TABLE message (ROWID INTEGER PRIMARY KEY, guid TEXT, text TEXT);")
        conn.close()
        with self.assertRaises(reader_base.UnknownSchemaError) as caught:
            messages_reader.read_messages(chat, now=NOW)
        self.assertEqual(caught.exception.table, "message")

    def test_system_rows_unsent_and_associations_are_skipped(self):
        # Real chat.db rows without text of their own (codes from the research on #37) are reported, not events.
        db = self.private_copy(self.chat_db)
        stamp = int(cocoa_seconds(NOW - timedelta(hours=1))) * 10**9
        rows = [  # guid, text, item_type, associated_message_type, date_retracted
            ("SYS-RENAME", None, 2, 0, 0), ("SYS-ADDED", None, 1, 0, 0), ("SYS-LOCATION", None, 4, 0, 0),
            ("UNSENT", None, 0, 0, stamp), ("PARTLY-UNSENT", "Still here", 0, 0, stamp),
            ("STICKER", None, 0, 1000, 0), ("POLL-VOTE", None, 0, 4000, 0),
        ]
        with sqlite3.connect(str(db)) as conn:
            conn.execute("ALTER TABLE message ADD COLUMN item_type INTEGER DEFAULT 0")
            conn.execute("ALTER TABLE message ADD COLUMN group_title TEXT")
            chat = conn.execute("SELECT ROWID FROM chat WHERE display_name = 'Family'").fetchone()[0]
            handle = conn.execute("SELECT ROWID FROM handle LIMIT 1").fetchone()[0]
            for guid, text, item_type, association, retracted in rows:
                rowid = conn.execute(
                    "INSERT INTO message (guid, text, handle_id, service, date, is_from_me, item_type, associated_message_type, "
                    "date_retracted, group_title) VALUES (?, ?, ?, 'iMessage', ?, 0, ?, ?, ?, ?)",
                    (guid, text, handle, stamp, item_type, association, retracted, "New name" if item_type == 2 else None),
                ).lastrowid
                conn.execute("INSERT INTO chat_message_join VALUES (?, ?, ?)", (chat, rowid, stamp))
        conn.close()
        result = messages_reader.read_messages(db, now=NOW)
        added = {r[0] for r in rows}
        self.assertEqual([e["source_record_id"] for e in result.events if e["source_record_id"] in added], ["PARTLY-UNSENT"])
        codes = sorted((p["record"], p["code"]) for p in result.problems if p["record"] in added)
        self.assertEqual(codes, [("POLL-VOTE", "reaction_skipped"), ("STICKER", "reaction_skipped"), ("SYS-ADDED", "system_item_skipped"),
                                 ("SYS-LOCATION", "system_item_skipped"), ("SYS-RENAME", "system_item_skipped"), ("UNSENT", "unsent_skipped")])
        self.assertEventsEqual([e for e in result.events if e["source_record_id"] not in added], self.expected("messages.jsonl"))

    def test_older_messages_layout_without_optional_columns(self):
        # Databases from before reactions and edits existed still read.
        db = self.private_copy(self.chat_db)
        with sqlite3.connect(str(db)) as conn:
            conn.execute("DELETE FROM message WHERE associated_message_type != 0")
            conn.execute("ALTER TABLE message RENAME TO message_new")
            conn.execute("CREATE TABLE message AS SELECT ROWID, guid, text, attributedBody, handle_id, service, date, is_from_me FROM message_new")
            conn.execute("DROP TABLE message_new")
        conn.close()
        result = messages_reader.read_messages(db, now=NOW)
        self.assertEqual(result.status.count, 14)
        self.assertNotIn("edited", {flag for e in result.events for flag in e["flags"]})


class DriftProfileTests(FixtureCase):
    """Edge case 20: the drift profile changes Mail's layout only; these readers are unaffected."""

    profile = "drift"

    def test_drift_profile_reads_as_expected(self):
        self.assertEventsEqual(notification_reader.read_notifications(self.notifications_db, now=NOW).events, self.expected("notifications.jsonl"))
        self.assertEventsEqual(messages_reader.read_messages(self.chat_db, now=NOW).events, self.expected("messages.jsonl"))


class StreamingTests(unittest.TestCase):
    """Edge case 19: memory stays flat however big the store is."""

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory(prefix="aegis-readers-bulk-")
        self.addCleanup(self.tmp.cleanup)

    def peak_while_streaming(self, db: Path):
        tracemalloc.start()
        try:
            status = messages_reader.read_messages(db, now=NOW, on_item=lambda kind, item: None).status
            _, peak = tracemalloc.get_traced_memory()
        finally:
            tracemalloc.stop()
        return status, peak

    def test_streaming_20000_messages_keeps_memory_flat(self):
        folder = Path(self.tmp.name)
        message_fixtures.build(folder, Rng(7), extra_rows=20_000)
        status, peak = self.peak_while_streaming(folder / "chat.db")
        self.assertEqual(status.count, 14 + 20_000)
        self.assertLess(peak, 4 * 2**20, "streamed reads must not keep events (keeping these takes about 30 MB)")

    @unittest.skipUnless(os.environ.get("AEGIS_FIXTURES_HUGE"), "set AEGIS_FIXTURES_HUGE=1 to stream the large profile")
    def test_streaming_the_huge_profile(self):
        out = Path(self.tmp.name) / "huge"
        generate.generate(out, huge=True)
        status, peak = self.peak_while_streaming(out / "messages" / "chat.db")
        self.assertEqual(status.count, 14 + 200_000)
        self.assertLess(peak, 4 * 2**20)


class TypedstreamTests(unittest.TestCase):
    def test_round_trips_short_long_and_very_long_text(self):
        for text in ("hi", "hello 👋", "x" * 200, "é" * 40_000):
            self.assertEqual(typedstream_reader.text_from_attributed_body(typedstream.attributed_body(text)), text)

    def test_invalid_utf8_becomes_replacement_characters(self):
        blob = typedstream.attributed_body_from_bytes(b"ok \xed\xa0\x80 ok", characters=7)
        self.assertEqual(typedstream_reader.text_from_attributed_body(blob), "ok \ufffd\ufffd\ufffd ok")

    def test_rejects_corrupt_truncated_and_foreign_blobs(self):
        good = typedstream.attributed_body("a message long enough to cut short")
        cut = good[: good.index(b"\x84\x01+") + 6]
        for blob in (typedstream.corrupt(), cut, b"bplist00 not a typedstream", b"", None):
            with self.assertRaises(ValueError, msg=repr(blob)[:40]):
                typedstream_reader.text_from_attributed_body(blob)


class CommandLineTests(FixtureCase):
    def run_cli(self, *args):
        return subprocess.run([sys.executable, str(HERE / "read.py"), *args], capture_output=True, text=True, timeout=60)

    def test_prints_counts_only_and_saves_private_files(self):
        saved = Path(self.tmp.name) / "saved"
        run = self.run_cli("--fixtures", str(self.out), "--save", "--out", str(saved))
        self.assertEqual(run.returncode, 0, run.stderr)
        self.assertRegex(run.stdout, r"notifications\s+ok\s+events 11 ")
        self.assertRegex(run.stdout, r"messages\s+ok\s+events 14 ")
        texts = {e["body"] for e in self.expected("notifications.jsonl") + self.expected("messages.jsonl") if len(e["body"]) > 3}
        self.assertFalse([t for t in texts if t in run.stdout + run.stderr], "the command line must never print message text")
        for name, expected in (("notifications", "notifications.jsonl"), ("messages", "messages.jsonl")):
            path = saved / f"{name}-events.jsonl"
            self.assertEqual(path.stat().st_mode & 0o777, 0o600)
            self.assertEventsEqual([json.loads(line) for line in path.read_text(encoding="utf-8").splitlines()], self.expected(expected))

    def test_missing_store_fails_with_advice(self):
        out = Path(self.tmp.name) / "partial"
        shutil.copytree(self.out, out)
        (out / "messages" / "chat.db").unlink()
        run = self.run_cli("--fixtures", str(out), "--source", "messages")
        self.assertEqual(run.returncode, 1)
        self.assertIn("not_found", run.stdout)
        self.assertIn("->", run.stdout)


